// src/content/index.ts
import { LLMProvider } from '../llm'

export async function generateContent(db: D1Database, agentId: string, candidate: { id: string, title: string }, llm: LLMProvider, cycleId: string) {
  try {
    // 1. Fetch sources for candidate
    const { results: sources } = await db.prepare(
      "SELECT s.id, s.url FROM candidate_sources cs JOIN sources s ON cs.source_id = s.id WHERE cs.candidate_id = ?"
    ).bind(candidate.id).all<{ id: string, url: string }>();

    if (sources.length === 0) return false;

    // 2. Generate Content
    const postData = await llm.generateStructured<{ text: string, rationale: string }>(
      `CONTENT_GENERATION: Write an insightful, thesis-driven post about the following topic. Do not just summarize. Focus on second-order consequences. Topic: ${candidate.title}`,
      { text: "string", rationale: "string" }
    );

    const now = new Date().toISOString();
    const postId = crypto.randomUUID();

    // 3. Persist Post
    await db.prepare(
      "INSERT INTO posts (id, agent_id, candidate_id, text, rationale, status, created_at, published_at) VALUES (?, ?, ?, ?, ?, 'PUBLISHED', ?, ?)"
    ).bind(postId, agentId, candidate.id, postData.text, postData.rationale, now, now).run();

    // 4. Link Sources
    for (const source of sources) {
      await db.prepare(
        "INSERT INTO post_sources (post_id, source_id, relevance_score) VALUES (?, ?, 1.0)"
      ).bind(postId, source.id).run();
    }

    // 5. Update Candidate Status
    await db.prepare("UPDATE candidates SET status = 'PUBLISHED' WHERE id = ?").bind(candidate.id).run();

    // 6. Record Publication Event
    const eventId = crypto.randomUUID();
    await db.prepare(
      "INSERT INTO publication_events (id, agent_id, post_id, event_type, status, created_at) VALUES (?, ?, ?, 'PUBLISHED', 'SUCCESS', ?)"
    ).bind(eventId, agentId, postId, now).run();

    return true;
  } catch (error) {
    console.error(`Error generating content for candidate ${candidate.id}:`, error);
    return false;
  }
}
