// src/editorial/index.ts
import { LLMProvider } from '../llm'

export async function evaluateCandidates(db: D1Database, agentId: string, llm: LLMProvider, cycleId: string) {
  // Fetch pending candidates
  const { results: candidates } = await db.prepare(
    "SELECT id, title FROM candidates WHERE agent_id = ? AND status = 'PENDING'"
  ).bind(agentId).all<{ id: string, title: string }>();

  const approvedCandidates = [];
  const now = new Date().toISOString();

  for (const candidate of candidates) {
    try {
      const decision = await llm.generateStructured<{ decision: string, rationale: string, score: number }>(
        `EDITORIAL_JUDGMENT: Evaluate if this technology topic is worth publishing based on second-order effects. Topic: ${candidate.title}`,
        { decision: "PUBLISH|REJECT", rationale: "string", score: "number" }
      );

      const decisionId = crypto.randomUUID();
      await db.prepare(
        "INSERT INTO editorial_decisions (id, agent_id, candidate_id, decision, rationale, score, decided_at) VALUES (?, ?, ?, ?, ?, ?, ?)"
      ).bind(decisionId, agentId, candidate.id, decision.decision, decision.rationale, decision.score, now).run();

      if (decision.decision === 'PUBLISH' && decision.score > 0.7) {
        await db.prepare("UPDATE candidates SET status = 'APPROVED' WHERE id = ?").bind(candidate.id).run();
        approvedCandidates.push(candidate);
        await db.prepare("UPDATE runtime_cycles SET candidates_approved = candidates_approved + 1 WHERE id = ?").bind(cycleId).run();
      } else {
        await db.prepare("UPDATE candidates SET status = 'REJECTED' WHERE id = ?").bind(candidate.id).run();
        await db.prepare("UPDATE runtime_cycles SET candidates_rejected = candidates_rejected + 1 WHERE id = ?").bind(cycleId).run();
      }
    } catch (e) {
      console.error(`Error evaluating candidate ${candidate.id}:`, e);
    }
  }

  return approvedCandidates;
}
