export interface LLMProvider {
  generate(prompt: string, model?: string): Promise<string>;
  generateStructured<T>(prompt: string, schema: any, model?: string): Promise<T>;
}

export class MockLLMProvider implements LLMProvider {
  async generate(prompt: string, model?: string): Promise<string> {
    return 'Mock generated text';
  }

  async generateStructured<T>(prompt: string, schema: any, model?: string): Promise<T> {
    // Basic heuristics to return appropriate mock data based on prompt
    if (prompt.includes('EDITORIAL_JUDGMENT')) {
      return { decision: 'PUBLISH', rationale: 'This topic has significant second-order effects.', score: 0.85 } as any;
    }
    if (prompt.includes('CONTENT_GENERATION')) {
      return { 
        text: 'This is an insightful post about the newly discovered technology event. It changes the infrastructure economics permanently.', 
        rationale: 'Selected due to its strategic implications.',
      } as any;
    }
    return {} as any;
  }
}

// In a real implementation we would have OpenAILLMProvider or similar
export class FetchLLMProvider implements LLMProvider {
  constructor(private apiKey: string, private endpoint: string = 'https://api.openai.com/v1/chat/completions') {}

  async generate(prompt: string, model: string = 'gpt-4o-mini'): Promise<string> {
    const res = await fetch(this.endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.apiKey}`
      },
      body: JSON.stringify({
        model,
        messages: [{ role: 'user', content: prompt }]
      })
    });
    if (!res.ok) throw new Error(`LLM Error: ${res.status}`);
    const data = await res.json() as any;
    return data.choices[0].message.content;
  }

  async generateStructured<T>(prompt: string, schema: any, model: string = 'gpt-4o-mini'): Promise<T> {
    // Simple JSON prompt injection (or use functions/structured output)
    const structuredPrompt = `${prompt}\n\nYou must return your output strictly as a JSON object matching this schema: ${JSON.stringify(schema)}\nDo not include markdown blocks.`;
    const res = await this.generate(structuredPrompt, model);
    try {
      const cleanJson = res.replace(/```json/g, '').replace(/```/g, '').trim();
      return JSON.parse(cleanJson) as T;
    } catch (e) {
      throw new Error('Failed to parse LLM structured output');
    }
  }
}
