// src/discovery/index.ts
export async function discoverCandidates(db: D1Database, agentId: string) {
  // Simple Hacker News discovery
  try {
    const response = await fetch('https://hacker-news.firebaseio.com/v0/topstories.json');
    if (!response.ok) return;
    
    const ids = await response.json() as number[];
    const topIds = ids.slice(0, 10); // Fetch top 10 to keep it lightweight

    for (const id of topIds) {
      const itemRes = await fetch(`https://hacker-news.firebaseio.com/v0/item/${id}.json`);
      if (!itemRes.ok) continue;
      
      const item = await itemRes.json() as any;
      if (!item || !item.url || !item.title) continue;

      // Check if source already exists
      const existing = await db.prepare(
        "SELECT id FROM sources WHERE agent_id = ? AND url = ?"
      ).bind(agentId, item.url).first();

      if (existing) continue;

      // Create new source
      const sourceId = crypto.randomUUID();
      const now = new Date().toISOString();
      await db.prepare(
        "INSERT INTO sources (id, agent_id, url, source_type, title, status, discovered_at) VALUES (?, ?, ?, 'HACKER_NEWS', ?, 'DISCOVERED', ?)"
      ).bind(sourceId, agentId, item.url, item.title, now).run();

      // Create candidate
      const candidateId = crypto.randomUUID();
      await db.prepare(
        "INSERT INTO candidates (id, agent_id, title, status, discovered_at) VALUES (?, ?, ?, 'PENDING', ?)"
      ).bind(candidateId, agentId, item.title, now).run();

      // Link candidate and source
      await db.prepare(
        "INSERT INTO candidate_sources (candidate_id, source_id, relationship) VALUES (?, ?, 'PRIMARY')"
      ).bind(candidateId, sourceId).run();
    }
  } catch (error) {
    console.error('Discovery Error:', error);
  }
}
